!===========================================
! Author: Elmo Tempel (elmo.tempel@ut.ee)
!===========================================
!
!> Standalone helper program that deliberately triggers `error stop` paths in
!> the parquet module. It is invoked as a subprocess (via `fpm test
!> error_scenarios -- <scenario>`) from test_errors.f90, because a Fortran
!> `error stop` aborts the whole process and cannot be caught in-process by
!> test-drive. The exit code (0 = no error stop reached, nonzero = aborted)
!> is the observable result.
program error_scenarios
    use parquet
    use parquet_maml_base, only: parquet_maml_file, get_parquet_maml
    use parquet_strings, only : parquet_string_column, parquet_string
    ! parquet_emit_info is deliberately PRIVATE in the `parquet` facade (it is an output
    ! channel, not user API), so the informational-channel scenario imports it from the
    ! settings module directly.
    use parquet_settings, only : parquet_emit_info, parquet_emit_warning
    use parquet_columns
    use parquet_list, only : parquet_list_column, parquet_list_row
    ! `pf_query_disc_runs` is deliberately NOT reachable through the `parquet` facade --
    ! src/parquet.f90 privatises it -- so naming its own module is how a caller reaches it,
    ! and this import is the documented route rather than a workaround.
    use parquet_healpix, only : pf_query_disc_runs
    use parquet_index, only : pf_index_map, pf_index_pool, pf_index_max_components, pf_index_multimap, &
        parquet_debug_index_partition, parquet_debug_index_spills, &
        parquet_debug_set_index_pair_limit, parquet_debug_set_index_string_hash_bits
    use parquet_table_example, only : parquet_table_test
    ! The quadrature scenarios' integrands: module procedures shared with test_integrate.f90,
    ! so a scenario and a test can name the same integrand and neither reaches an internal one.
    use test_integrate_support, only : runge
    ! The interpolation scenarios' non-finite fixtures, built with `ieee_value` so no fixture's own
    ! arithmetic raises the flag the library is being asked about.
    use test_interpolate_support, only : nan_value, positive_infinity
    ! The optimisation scenarios' objectives: module procedures and module-level types shared with
    ! test_optimize.f90, so a scenario and a test name the same objective and neither reaches an
    ! internal procedure.
    use test_optimize_support, only : quad1d, sphere, always_nan, nan_beyond_two, unit_disc, &
        dist12, outside_disc, negative_count_disc, nan_constraint_disc
    ! The root-finding scenarios' functions: module procedures shared with test_root.f90, so a
    ! scenario and a test name the same function and neither reaches an internal procedure.
    use test_root_support, only : root_sq2, root_line_03, root_nan_beyond_two
    use parquet_prima, only : pf_minimize_bobyqa, pf_minimize_lincoa, pf_minimize_cobyla
    use parquet_optimize, only : pf_minimize_scalar, pf_minimize_simplex, pf_minimize_de, &
        pf_minimize_multistart
    use parquet_tables
    ! The grouping scenarios' callbacks: module procedures, since an internal one of this
    ! program cannot be passed as a callback under every supported compiler.
    use test_group_callbacks, only : scenario_group_row_sum, scenario_group_two, scenario_group_reducer, &
        scenario_group_col_mean
    use parquet_temporal, only : parquet_date, parquet_time, parquet_timestamp, &
        parquet_unit_seconds, parquet_unit_millis, parquet_unit_nanos
    use iso_fortran_env, only : int32, int64, real32, real64
    !$ use omp_lib, only : omp_get_max_threads, omp_get_thread_num
    implicit none

    !> A second concrete table type, existing only so the %clone same-type guard has something to
    !! be told apart from. Stands in for what tools/generate_parquet_table.sh will emit later: a
    !! table extended with predefined-column accessors, which a clone must not silently drop.
    type, extends(parquet_table) :: extended_table
        integer :: marker = 0 !! never read; the type's identity is the whole point.
    end type extended_table

    character(len=64) :: scenario
    integer :: nargs

    nargs = command_argument_count()
    if (nargs < 1) then
        ! No scenario requested: this happens when `fpm test` auto-runs every
        ! test target with no arguments. Exit cleanly and silently rather than
        ! failing, since this program is only meant to be driven (with an
        ! explicit scenario) as a subprocess from test_errors.f90.
        stop
    end if
    call get_command_argument(1, scenario)

    select case (trim(scenario))
    case ("ok")
        continue
    case ("print_stat_smoke")
        call scenario_print_stat_smoke()
    case ("print_stat_all_types")
        call scenario_print_stat_all_types()
    case ("print_stat_default_scalar_type")
        call scenario_print_stat_default_scalar_type()
    case ("print_stat_filtered_rows")
