        call spatial_los_cloud(64, x, y, z, d)
        d = 1.0_real64
        call sx%build(x, y, z, radius=20.0_real64, los=d)   ! -> aborts
        print '(a,i0)', "unexpectedly built an index over a constant los, n=", sx%size()
    end subroutine scenario_spatial_los_constant

