    !> An explicit thread count below one.
    subroutine scenario_healpix_bulk_threads_zero()
        real(real64) :: theta(3), phi(3)
        integer(int64) :: ipix(3)

        theta = [0.1_real64, 0.5_real64, 1.0_real64]
